# frozen_string_literal: true

require "base64"
require "json"
require "zlib"

# Immutable, run-independent compiler fixture. The compressed payload contains
# one 02A parent cut and its matching legacy 02B shell packet. Keeping the
# snapshot under scripts/tests prevents dirty production artifacts from acting
# as golden test data.
module IdolPromptPacketCompileFixture
  PAYLOAD = <<~BASE64.delete("\n")
    
  BASE64

  SHELL_METADATA = <<~BASE64.delete("\n")
    
  BASE64

  def self.load
    payload = JSON.parse(Zlib::Inflate.inflate(Base64.strict_decode64(PAYLOAD)))
    shell_metadata = JSON.parse(Zlib::Inflate.inflate(Base64.strict_decode64(SHELL_METADATA)))
    payload["shell"] = shell_metadata.merge(payload.fetch("shell"))
    payload
  end
end
